import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matrix_scale_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matrix_scale_kernel(const float* input, float scalar, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        output[idx] = input[idx] * scalar;
    }
}

torch::Tensor matrix_scale_cuda(torch::Tensor input, float scalar) {
    auto output = torch::zeros_like(input);
    int num_elements = input.numel();

    const int threads_per_block = 256;
    int blocks_per_grid = (num_elements + threads_per_block - 1) / threads_per_block;

    matrix_scale_kernel<<<blocks_per_grid, threads_per_block>>>(
        input.data_ptr<float>(),
        scalar,
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}
"""

matrix_scale_cpp_source = "torch::Tensor matrix_scale_cuda(torch::Tensor input, float scalar);"

matrix_scale = load_inline(
    name="matrix_scale",
    cpp_sources=matrix_scale_cpp_source,
    cuda_sources=matrix_scale_source,
    functions=["matrix_scale_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matrix_scale_op = matrix_scale

    def forward(self, A: torch.Tensor, s: float) -> torch.Tensor:
        return self.matrix_scale_op.matrix_scale_cuda(A, s)
